## 1️⃣ `src/types.ts` – Core Types  

```ts
// src/types.ts
export enum JobStatus {
  Pending = 'pending',
  Delayed = 'delayed',
  InProgress = 'in_progress',
  Completed = 'completed',
  Failed = 'failed',
  DeadLetter = 'dead_letter',
}

/**
 * Generic job definition.
 * T is the shape of the payload the consumer cares about.
 */
export interface Job<T = unknown> {
  /** Unique identifier (UUID v4) */
  id: string;
  /** Payload that the worker will process */
  payload: T;
  /** Number of attempts already made */
  attempts: number;
  /** Maximum allowed attempts before moving to DLQ */
  maxAttempts: number;
  /** Current status of the job */
  status: JobStatus;
  /** Timestamp (ms since epoch) when the job was created */
  createdAt: number;
  /** Timestamp (ms since epoch) of the last status change */
  updatedAt: number;
  /** Optional error message from the last failure */
  error?: string;
}

/**
 * Options used when constructing a JobQueue.
 */
export interface QueueOptions {
  /** Logical name of the queue – used as a Redis key prefix */
  name: string;
  /** ioredis connection options (or a ready ioredis instance) */
  redis?: any; // will be injected by RedisClient
  /** Max concurrent jobs a worker may process */
  concurrency?: number;
  /** Default max attempts for jobs pushed without explicit maxAttempts */
  defaultMaxAttempts?: number;
  /** Base delay (ms) for exponential back‑off */
  backoffBaseMs?: number;
  /** Upper bound (ms) for back‑off delay */
  backoffCapMs?: number;
  /** Name of the dead‑letter queue (defaults to `${name}:dlq`) */
  dlqName?: string;
}

/**
 * Signature of a worker handler.
 * Must resolve on success or reject with an Error on failure.
 */
export type WorkerHandler<T = unknown> = (job: Job<T>) => Promise<void>;
```

