## 2️⃣ `src/RedisClient.ts` – Resilient Redis Wrapper  

```ts
// src/RedisClient.ts
import IORedis, { Redis, RedisOptions } from 'ioredis';
import { EventEmitter } from 'events';

/**
 * Centralised Redis client with:
 *  - Automatic reconnection (handled by ioredis)
 *  - Periodic health‑check ping
 *  - Centralised error logging
 *  - EventEmitter interface for external observers
 */
export class RedisClient extends EventEmitter {
  private client: Redis;
  private pingIntervalMs: number;
  private pingTimer?: NodeJS.Timeout;

  constructor(options: RedisOptions = {}, pingIntervalMs = 5_000) {
    super();
    this.client = new IORedis(options);
    this.pingIntervalMs = pingIntervalMs;
    this.attachEventHandlers();
    this.startHealthCheck();
  }

  /** Expose the underlying ioredis instance for advanced use */
  public get raw(): Redis {
    return this.client;
  }

  /** Gracefully close the connection */
  public async quit(): Promise<void> {
    this.stopHealthCheck();
    await this.client.quit();
  }

  /** Simple wrapper for `evalsha` that falls back to `eval` if script not cached */
  public async eval(
    script: string,
    keys: string[],
    args: (string | number)[]
  ): Promise<any> {
    const sha = IORedis.Command.sha1(script);
    try {
      return await this.client.evalsha(sha, keys.length, ...keys, ...args);
    } catch (err: any) {
      // If script is not cached, ioredis throws NOSCRIPT; fall back to eval
      if (err?.message?.includes('NOSCRIPT')) {
        return await this.client.eval(script, keys.length, ...keys, ...args);
      }
      throw err;
    }
  }

  /** --------------------------------------------------------------
   *  Private helpers
   * -------------------------------------------------------------- */
  private attachEventHandlers(): void {
    this.client.on('error', (err) => {
      this.emit('error', err);
      console.error('[Redis] error:', err);
    });

    this.client.on('connect', () => {
      this.emit('connect');
      console.info('[Redis] connected');
    });

    this.client.on('ready', () => {
      this.emit('ready');
      console.info('[Redis] ready');
    });

    this.client.on('reconnecting', (delay) => {
      this.emit('reconnecting', delay);
      console.warn(`[Redis] reconnecting in ${delay} ms`);
    });

    this.client.on('end', () => {
      this.emit('end');
      console.warn('[Redis] connection closed');
    });
  }

  private startHealthCheck(): void {
    this.pingTimer = setInterval(async () => {
      try {
        const latency = await this.client.ping();
        // ioredis returns 'PONG' – we just log latency for observability
        if (latency !== 'PONG') {
          console.warn('[Redis] unexpected ping response:', latency);
        }
      } catch (err) {
        console.error('[Redis] ping failed:', err);
      }
    }, this.pingIntervalMs);
  }

  private stopHealthCheck(): void {
    if (this.pingTimer) {
      clearInterval(this.pingTimer);
      this.pingTimer = undefined;
    }
  }
}
```

