## 3️⃣ `src/JobQueue.ts` – Queue Core (Lua‑backed)  

```ts
// src/JobQueue.ts
import { v4 as uuidv4 } from 'uuid';
import { RedisClient } from './RedisClient';
import {
  Job,
  JobStatus,
  QueueOptions,
  WorkerHandler,
} from './types';

/**
 * JobQueue implements:
 *  - push (immediate or delayed)
 *  - pop (atomic fetch + status transition)
 *  - retry with exponential back‑off
 *  - dead‑letter handling
 *
 * All state lives in Redis under keys prefixed with `${options.name}:*`.
 */
export class JobQueue<T = unknown> {
  private readonly opts: Required<QueueOptions>;
  private readonly redis: RedisClient;

  // Key helpers
  private key(prefix: string): string {
    return `${this.opts.name}:${prefix}`;
  }

  private readonly KEYS = {
    ready: this.key('ready'),               // List – jobs ready to be processed
    delayed: this.key('delayed'),           // Sorted set – jobs waiting for future timestamp
    payloads: this.key('payloads'),         // Hash – jobId => JSON string
    status: this.key('status'),             // Hash – jobId => JobStatus
    attempts: this.key('attempts'),         // Hash – jobId => attempts count
    dlq: this.opts.dlqName,                 // List – dead‑letter queue
    processing: this.key('processing'),     // Hash – jobId => timestamp (optional for visibility)
  };

  // Lua script for atomic pop from ready list and status update
  private readonly POP_SCRIPT = `
    local readyKey = KEYS[1]
    local payloadKey = KEYS[2]
    local statusKey = KEYS[3]
    local attemptsKey = KEYS[4]
    local processingKey = KEYS[5]

    local jobId = redis.call('LPOP', readyKey)
    if not jobId then
      return nil
    end

    -- Move job to processing hash with current timestamp
    redis.call('HSET', processingKey, jobId, tostring(ARGV[1]))

    -- Update status
    redis.call('HSET', statusKey, jobId, '${JobStatus.InProgress}')

    -- Return the payload
    local payload = redis.call('HGET', payloadKey, jobId)
    return {jobId, payload}
  `;

  // Lua script for moving a job to DLQ atomically
  private readonly MOVE_TO_DLQ_SCRIPT = `
    local dlqKey = KEYS[1]
    local payloadKey = KEYS[2]
    local statusKey = KEYS[3]
    local attemptsKey = KEYS[4]
    local processingKey = KEYS[5]

    local jobId = ARGV[1]
    local errorMsg = ARGV[2]

    -- Remove from processing set (if present)
    redis.call('HDEL', processingKey, jobId)

    -- Update status and error
    redis.call('HSET', statusKey, jobId, '${JobStatus.DeadLetter}')
    redis.call('HSET', payloadKey, jobId, errorMsg) -- store error in payload for inspection

    -- Push to DLQ list
    redis.call('RPUSH', dlqKey, jobId)

    return 1
  `;

  constructor(redisClient: RedisClient, options: QueueOptions) {
    this.redis = redisClient;
    this.opts = {
      name: options.name,
      concurrency: options.concurrency ?? 5,
      defaultMaxAttempts: options.defaultMaxAttempts ?? 5,
      backoffBaseMs: options.backoffBaseMs ?? 500,
      backoffCapMs: options.backoffCapMs ?? 30_000,
      dlqName: options.dlqName ?? `${options.name}:dlq`,
      redis: options.redis,
    };
  }

  /** -----------------------------------------------------------------
   *  Public API
   * ----------------------------------------------------------------- */

  /**
   * Push a new job onto the queue.
   * @param payload   The job payload.
   * @param delayMs   Optional delay in milliseconds (for scheduled jobs).
   * @param maxAttempts Optional per‑job max attempts (defaults to queue default).
   */
  public async push(
    payload: T,
    delayMs = 0,
    maxAttempts?: number
  ): Promise<Job<T>> {
    const id = uuidv4();
    const now = Date.now();
    const job: Job<T> = {
      id,
      payload,
      attempts: 0,
      maxAttempts: maxAttempts ?? this.opts.defaultMaxAttempts,
      status: delayMs > 0 ? JobStatus.Delayed : JobStatus.Pending,
      createdAt: now,
      updatedAt: now,
    };

    const multi = this.redis.raw.multi();

    // Store payload (as JSON) and status
    multi.hset(this.KEYS.payloads, id, JSON.stringify(job));
    multi.hset(this.KEYS.status, id, job.status);
    multi.hset(this.KEYS.attempts, id, '0');

    if (delayMs > 0) {
      const scheduleTs = now + delayMs;
      multi.zadd(this.KEYS.delayed, scheduleTs.toString(), id);
    } else {
      // Immediate jobs go to the ready list (FIFO)
      multi.rpush(this.KEYS.ready, id);
    }

    await multi.exec();
    return job;
  }

  /**
   * Atomically pop a job from the ready queue.
   * Returns `null` if the queue is empty.
   */
  public async pop(): Promise<Job<T> | null> {
    const now = Date.now();
    const result = await this.redis.eval(
      this.POP_SCRIPT,
      [this.KEYS.ready, this.KEYS.payloads, this.KEYS.status, this.KEYS.attempts, this.KEYS.processing],
      [now]
    );

    if (!result) {
      return null;
    }

    const [jobId, payloadStr] = result as [string, string];
    const job: Job<T> = JSON.parse(payloadStr);
    // Ensure status reflects the in‑progress state (Lua already set it)
    job.status = JobStatus.InProgress;
    job.updatedAt = now;
    return job;
  }

  /**
   * Called by the worker when a job finishes successfully.
   */
  public async markCompleted(job: Job<T>): Promise<void> {
    const now = Date.now();
    const multi = this.redis.raw.multi();
    multi.hset(this.KEYS.status, job.id, JobStatus.Completed);
    multi.hdel(this.KEYS.processing, job.id);
    multi.hset(this.KEYS.payloads, job.id, JSON.stringify({ ...job, status: JobStatus.Completed, updatedAt: now }));
    await multi.exec();
  }

  /**
   * Called by the worker when a job fails.
   * Handles retry with exponential back‑off or moves to DLQ.
   */
  public async handleFailure(job: Job<T>, error: Error): Promise<void> {
    const attempts = job.attempts + 1;
    const now = Date.now();

    if (attempts >= job.maxAttempts) {
      // Move to DLQ
      await this.moveToDLQ(job.id, error.message);
      return;
    }

